// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    address deployer = address(uint160(0xE0A));

    function setUp() public {
        address __invmut_eoa = address(uint160(0xE0A));
        vm.deal(__invmut_eoa, 100 ether);
        vm.startPrank(__invmut_eoa, __invmut_eoa);
        c = new PoCGame(address(this), 0);
        vm.stopPrank();
    }

    function testFuzz_property(address tokenOwner, uint256 tokens) public {
        vm.assume(tokenOwner != address(0));
        vm.assume(tokenOwner != address(this)); // whale is address(this); bug only separates when tokenOwner != whale
        tokens = bound(tokens, 1, 1e24);

        RealToken tk = new RealToken(address(c), tokens);

        vm.startPrank(deployer, deployer);
        bool ok = c.transferAnyERC20Token(address(tk), tokenOwner, tokens);
        vm.stopPrank();

        // General rule: the transfer recipient is exactly `tokenOwner` — its balance
        // rose by `tokens` and the whale's balance stayed at zero.
        assertTrue(ok && tk.balances(tokenOwner) == tokens && tk.balances(address(this)) == 0);
    }
}

contract RealToken {
    mapping(address => uint256) public balances;
    constructor(address to, uint256 amt) { balances[to] = amt; }
    function transfer(address to, uint256 tokens) public returns (bool) {
        require(balances[msg.sender] >= tokens, "bal");
        balances[msg.sender] -= tokens;
        balances[to] += tokens;
        return true;
    }
}
